const slides = [
  { title: 'INGENIERÍA DE SOFTWARE I', eyebrow: '01 · Unidad III', body: `<p class="lede">UNIDAD III – REQUERIMIENTOS DE SOFTWARE</p><p>Prof. Lic. Guillermo Jacobo González Rodas Mst. PMP</p>`, visual: `<div class="visual-title">Unidad III</div><div class="quote">Requerimientos de Software</div>`, note: '<strong>Desarrollo:</strong> Presentar la Unidad III como el momento en que definimos qué debe hacer el sistema antes de construir nada: los requerimientos son la base del éxito del proyecto. Ubicar el punto en el recorrido del curso: después de estudiar los procesos, ahora decidimos qué construir.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): decidir qué operaciones de cambio, tasas y controles debe soportar el sistema antes de diseñar nada. Segundo contexto industrial: en salud, un sistema de historia clínica exige definir qué registros y permisos se requieren antes de diseñar la interfaz.<br><br><strong>Reflexión docente:</strong> Un requerimiento mal entendido se multiplica en costos y retrabajo más adelante; definirlo bien al inicio es la inversión más barata del proyecto.<br><br><strong>Pregunta desafío:</strong> ¿qué puede pasar si un sistema se construye sin acordar antes sus requerimientos?<br><br><strong>Respuestas posibles:</strong> 1. Se construye lo que el equipo supone y no lo que el usuario necesita. 2. Se descubren tarde las discrepancias y se retrabaja. 3. Se gastan recursos en funciones que nadie usa.<br><br><strong>Advertencia:</strong> la portada ubica el tema; los conceptos se desarrollan en los siguientes slides.' },
  { title: 'OBJETIVOS', eyebrow: '02 · Objetivos', body: `<ul><li>Comprender qué son los requerimientos de software y por qué son importantes</li><li>Familiarizarse con los diferentes tipos de requerimientos</li><li>Aprender técnicas y herramientas para la obtención, análisis y gestión de requerimientos</li></ul>`, visual: `<div class="visual-title">Al finalizar</div><div class="cards"><div class="card"><span class="number">01</span><p>Qué son y por qué importan</p></div><div class="card"><span class="number">02</span><p>Tipos de requerimientos</p></div><div class="card"><span class="number">03</span><p>Técnicas y herramientas</p></div></div>`, note: '<strong>Desarrollo:</strong> Tomar los objetivos como criterios de aceptación de la clase: comprender qué son los requerimientos y por qué importan, distinguir los tipos y conocer técnicas y herramientas de obtención, análisis y gestión. Al cierre, volver a ellos para comprobar si podemos aplicarlos.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): al cierre deberíamos poder clasificar una regla de cambio de divisas como funcional o no funcional. Segundo contexto industrial: en transporte, distinguir un requisito de rastreo de envíos (funcional) de uno de rendimiento (no funcional).<br><br><strong>Reflexión docente:</strong> Un objetivo se demuestra aplicándolo a un caso, no repitiendo la frase.<br><br><strong>Pregunta desafío:</strong> ¿cómo demostrarían que comprendieron qué es un requerimiento?<br><br><strong>Respuestas posibles:</strong> 1. Definiéndolo con palabras propias. 2. Clasificando ejemplos reales en funcionales y no funcionales. 3. Justificando por qué un requerimiento es importante para el éxito del sistema.<br><br><strong>Advertencia:</strong> no confundir comprender un término con poder aplicarlo a un caso concreto.' },
  { title: 'CONTENIDO', eyebrow: '03 · Contenido', body: `<ul><li>Requerimientos de Software</li><li>Tipos de Requerimientos</li><li>Ingeniería de Requerimientos</li><li>Proceso de Requerimientos de Software</li><li>Obtención de Requerimientos</li><li>Análisis de Requerimientos</li><li>Especificación de Requerimientos</li><li>Verificación de Requerimientos</li><li>Validación de Requerimientos</li><li>Gestión de Requerimientos</li></ul>`, visual: `<div class="visual-title">Recorrido</div><div class="sequence-card" aria-label="Secuencia temática de la unidad"><div class="sequence-step"><span class="sequence-index">01</span><strong>Tipos</strong><small>Funcionales y no funcionales</small></div><div class="sequence-step"><span class="sequence-index">02</span><strong>Obtención</strong><small>Fuentes y técnicas</small></div><div class="sequence-step"><span class="sequence-index">03</span><strong>Análisis</strong><small>Modelos y vistas</small></div><div class="sequence-step"><span class="sequence-index">04</span><strong>Especificación</strong><small>Documento SRS</small></div><div class="sequence-step"><span class="sequence-index">05</span><strong>Verificación y validación</strong><small>Control de calidad</small></div><div class="sequence-step"><span class="sequence-index">06</span><strong>Gestión</strong><small>Cambios y trazabilidad</small></div></div>`, note: '<strong>Desarrollo:</strong> Recorrer el mapa de la unidad: qué es un requerimiento, sus tipos, la ingeniería de requerimientos y el proceso completo con obtención, análisis, especificación, verificación, validación y gestión.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): el mapa completo aplica al sistema de cambio de divisas, desde el relevamiento de necesidades hasta el control de cambios posteriores. Segundo contexto industrial: en banca, el mismo proceso se usa para definir un nuevo producto financiero.<br><br><strong>Reflexión docente:</strong> El orden no es decorativo: cada fase produce artefactos que alimentan la siguiente.<br><br><strong>Pregunta desafío:</strong> ¿qué diferencia esperan entre obtener y gestionar requerimientos?<br><br><strong>Respuestas posibles:</strong> 1. Obtener reúne necesidades; gestionar controla sus cambios. 2. La obtención ocurre al inicio; la gestión acompaña todo el proceso. 3. Sin gestión, un requerimiento nuevo puede llegar sin controlar su impacto.<br><br><strong>Advertencia:</strong> la lista de temas anticipa el recorrido; no los desarrolla todavía.' },
  { title: '¿Qué es un Requerimiento de Software?', eyebrow: '04 · Definición', body: `<div class="card"><p><strong>Propiedad que debe ser exhibida por un software para resolver un problema particular.</strong> (SWEBOK)</p><p class="reference">SWEBOK Guide. IEEE Computer Society.</p></div><ul><li><strong>Condición o capacidad</strong> que necesita el usuario para resolver un problema o conseguir un objetivo determinado.</li><li><strong>ERS</strong> – Documento formal de Especificación de Requisitos Software.</li><li><strong>SRS</strong> – Software Requirements Specification.</li></ul><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Dos lecturas</div><div class="quote">Propiedad del sistema<br><br>Capacidad para el usuario</div>`, note: '<strong>Desarrollo:</strong> Contrastar las dos definiciones: una desde el sistema (propiedad que debe exhibir para resolver un problema, según SWEBOK) y otra desde el usuario (condición o capacidad que necesita). Presentar ERS y SRS como el documento que formaliza la especificación de requisitos.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): "calcular la conversión entre divisas en tiempo real" es una capacidad que el usuario necesita y que el sistema debe exhibir. Segundo contexto industrial: en logística, "consultar el estado de un envío" es una capacidad que el sistema debe proveer.<br><br><strong>Reflexión docente:</strong> Las dos miradas conviven: un buen requerimiento satisface tanto la necesidad del usuario como la propiedad verificable del sistema.<br><br><strong>Pregunta desafío:</strong> ¿una misma frase puede ser un requerimiento válido para el usuario y para el sistema?<br><br><strong>Respuestas posibles:</strong> 1. Sí, si expresa una capacidad concreta y verificable. 2. No, si queda en un deseo general sin criterio de comprobación. 3. Depende de cuán concreta y medible sea la formulación.<br><br><strong>Advertencia:</strong> requerimiento y deseo no son lo mismo: un requerimiento se puede verificar.' },
  { title: 'Características de Requerimientos', eyebrow: '05 · Características', body: `<p>Los requisitos de un software suelen ser una combinación compleja de los requisitos de diferentes personas en diferentes niveles de una organización y del entorno en el cual operará el software.</p><p>Es fundamental que un requisito sea <strong>verificable</strong>.</p><p>Otros atributos que les caracterizan son:</p><ul><li><strong>Prioridad</strong></li><li><strong>Identificador único</strong></li></ul><p>Los requisitos deben ser lo más claros y no ambiguos que se pueda, y <strong>cuantificables</strong> (si es posible).</p><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Atributos clave</div><div class="cards"><div class="card"><h3>Verificable</h3><p>Se puede comprobar su cumplimiento</p></div><div class="card"><h3>Prioridad</h3><p>Jerarquiza la importancia</p></div><div class="card"><h3>Identificador único</h3><p>Permite trazabilidad</p></div><div class="card"><h3>Claro y no ambiguo</h3><p>Una única interpretación</p></div><div class="card"><h3>Cuantificable</h3><p>Medible siempre que sea posible</p></div></div>`, note: '<strong>Desarrollo:</strong> Explicar que los requisitos combinan necesidades de distintas personas y del entorno; destacar que un requisito debe ser verificable y comentar la prioridad, el identificador único, la claridad, la no ambigüedad y la cuantificación.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): "el sistema debe verificar la tasa vigente antes de cada operación" es verificable y puede tener prioridad alta y un identificador único (RF-010). Segundo contexto industrial: en telecomunicaciones, "tiempo máximo de disponibilidad del servicio" se puede cuantificar y verificar.<br><br><strong>Reflexión docente:</strong> Un requisito que no se puede verificar no se puede probar ni aceptar; por eso la verificabilidad es fundamental.<br><br><strong>Pregunta desafío:</strong> ¿cómo verificarían "la interfaz debe ser amigable"?<br><br><strong>Respuestas posibles:</strong> 1. No es verificable tal como está; exige reformularla con criterios medibles. 2. Podría convertirse en métricas de uso o de tareas completadas. 3. Se podría reformular como un requisito no funcional cuantitativo.<br><br><strong>Advertencia:</strong> atributos como la prioridad o el identificador no reemplazan la verificabilidad del requisito.' },
  { title: 'Tipos de Requerimientos', eyebrow: '06 · Tipos', body: `<p>Los requerimientos de software se clasifican en dos grandes grupos:</p><ul><li><strong>Requerimientos Funcionales:</strong> capacidades y servicios que el sistema debe proveer.</li><li><strong>Requerimientos No Funcionales:</strong> restricciones y propiedades de calidad del sistema.</li></ul><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Clasificación</div><div class="cards"><div class="card"><span class="number">F</span><p>Funcionales</p></div><div class="card"><span class="number">NF</span><p>No Funcionales</p></div></div>`, note: '<strong>Desarrollo:</strong> Presentar la clasificación base en funcionales y no funcionales; anunciar que ambos tipos conviven y se complementan en todo sistema.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): "convertir divisas" es funcional; "responder la consulta de tasas en menos de 2 segundos" es no funcional. Segundo contexto industrial: en seguros, "emitir una póliza" es funcional y "cumplir la normativa de protección de datos" es no funcional.<br><br><strong>Reflexión docente:</strong> Dividir en tipos ayuda a analizar, pero un sistema completo exige atender ambos grupos por igual.<br><br><strong>Pregunta desafío:</strong> ¿qué tipo se olvida con más frecuencia en los proyectos?<br><br><strong>Respuestas posibles:</strong> 1. Los no funcionales, porque no se ven en pantalla. 2. Los de rendimiento y seguridad, hasta que fallan. 3. Los de calidad, porque los equipos se concentran en funciones visibles.<br><br><strong>Advertencia:</strong> un sistema que cumple las funciones pero no las restricciones puede fallar en producción.' },
  { title: 'Requerimientos Funcionales', eyebrow: '07 · Funcionales', body: `<ul><li>Se refieren a las <strong>capacidades del sistema</strong>.</li><li>Describen las funciones que lleva a cabo el software, cómo debe reaccionar ante ciertas entradas y cómo debe comportarse en situaciones particulares.</li><li>Describen la funcionalidad o los servicios que se espera que éste provea.</li><li>Son declaraciones de los servicios que proveerá el sistema, de la manera en que éste reaccionará a entradas particulares.</li><li>En algunos casos, los requerimientos funcionales de los sistemas también declaran explícitamente lo que el sistema <strong>NO</strong> debe hacer.</li></ul><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Qué describen</div><div class="quote">Capacidades, reacciones a entradas y comportamiento en situaciones particulares</div>`, note: '<strong>Desarrollo:</strong> Definir los requerimientos funcionales como las capacidades y servicios del sistema: las funciones, las reacciones a entradas y el comportamiento en situaciones particulares; recordar que también declaran explícitamente lo que el sistema NO debe hacer.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): "el sistema debe validar que el cliente tenga fondos antes de autorizar la venta" y "no debe permitir operaciones con tasas vencidas". Segundo contexto industrial: en gobierno, un sistema de trámites debe rechazar solicitudes incompletas.<br><br><strong>Reflexión docente:</strong> Las declaraciones negativas también son funcionales: evitan comportamientos indeseados y fijan límites verificables.<br><br><strong>Pregunta desafío:</strong> ¿por qué conviene declarar explícitamente lo que el sistema NO debe hacer?<br><br><strong>Respuestas posibles:</strong> 1. Para que el equipo no lo implemente por descuido. 2. Para fijar límites verificables de comportamiento. 3. Para evitar interpretaciones divergentes entre clientes y desarrolladores.<br><br><strong>Advertencia:</strong> las declaraciones negativas deben ser tan verificables como las positivas.' },
  { title: 'Ejemplos de Requerimientos Funcionales', eyebrow: '08 · Ejemplos RF', body: `<p class="lede">Requerimientos funcionales típicos de un sistema de ventas:</p><div class="cards"><div class="card"><h3>RF1</h3><p>El sistema controlará el acceso y lo permitirá solamente a usuarios autorizados. Los usuarios deben ingresar al sistema con un nombre de usuario y contraseña.</p></div><div class="card"><h3>RF2</h3><p>El campo país consistirá en una lista de preselección. El país asociado a una dirección debe ser previamente registrado en el sistema.</p></div></div><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010.</p>`, visual: `<div class="visual-title">RF3 y RF4</div><div class="cards"><div class="card"><h3>RF3</h3><p>El campo estado, provincia o departamento consistirá en una lista de preselección. A los usuarios se les presentará únicamente los departamentos asociados al país seleccionado previamente.</p></div><div class="card"><h3>RF4</h3><p>El sistema enviará un correo electrónico cuando se registre alguna de las siguientes transacciones: pedido de venta de cliente, emisión de factura a cliente y registro de pago de cliente.</p></div></div>`, note: '<strong>Desarrollo:</strong> Recorrer los cuatro ejemplos: RF1 control de acceso, RF2 país como lista de preselección, RF3 departamentos dependientes del país elegido y RF4 envío de correos ante transacciones de venta. Resaltar cómo cada uno se puede verificar.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): RF4 se traduce a "el sistema envía un correo cuando se registra un pedido, una factura o un pago" y se prueba con datos de prueba. Segundo contexto industrial: en comercio electrónico, los mismos ejemplos aplican a cuentas, catálogos y notificaciones.<br><br><strong>Reflexión docente:</strong> Los ejemplos concretos vuelven comprensible la abstracción "requerimiento funcional".<br><br><strong>Pregunta desafío:</strong> ¿cómo probarían que se cumple RF1?<br><br><strong>Respuestas posibles:</strong> 1. Intentando ingresar sin credenciales y verificando el rechazo. 2. Validando que solo los usuarios autorizados acceden. 3. Registrando la operación de ingreso y su resultado.<br><br><strong>Advertencia:</strong> los ejemplos son ilustrativos; cada proyecto adapta su propio catálogo de requerimientos.' },
  { title: 'Requerimientos No Funcionales', eyebrow: '09 · No Funcionales', body: `<ul><li>Se refieren a las <strong>restricciones y requisitos de calidad</strong>.</li><li>Son restricciones sobre las funciones o servicios ofrecidos por el sistema.</li><li>Incluyen restricciones de tiempo, sobre el proceso de desarrollo, estándares, etc.</li><li>Se refieren a las <strong>propiedades emergentes</strong> del sistema: fiabilidad, respuesta en el tiempo y capacidad de almacenamiento.</li><li>También definen restricciones como la capacidad de los dispositivos de entrada/salida y la representación de datos utilizada en la interfaz del sistema.</li></ul><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Restricciones y calidad</div><div class="quote">No describen qué hace el sistema, sino cómo debe ser y bajo qué restricciones opera</div>`, note: '<strong>Desarrollo:</strong> Definir los no funcionales como restricciones y requisitos de calidad: tiempo, proceso de desarrollo, estándares, y propiedades emergentes como fiabilidad, tiempo de respuesta y almacenamiento; también restricciones de dispositivos de entrada/salida e interfaz.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): "el sistema debe operar 24x7 con una disponibilidad del 99,5%" es un requerimiento no funcional. Segundo contexto industrial: en banca, "las transacciones deben registrar auditoría completa" combina restricción y calidad.<br><br><strong>Reflexión docente:</strong> Los no funcionales condicionan la arquitectura tanto como los funcionales, aunque no sean visibles en pantalla.<br><br><strong>Pregunta desafío:</strong> ¿qué no funcional afectaría la elección de arquitectura de Global Exchange?<br><br><strong>Respuestas posibles:</strong> 1. El tiempo de respuesta de las tasas en tiempo real. 2. La seguridad y auditoría de las transacciones. 3. La capacidad de almacenamiento del histórico.<br><br><strong>Advertencia:</strong> omitir no funcionales suele manifestarse como una falla grave en producción.' },
  { title: 'Requerimientos No Funcionales', eyebrow: '10 · Clasificación RNF', body: `<p>Los requerimientos no funcionales se organizan en categorías según la fuente o el tipo de restricción que imponen.</p><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Clasificación de los requerimientos no funcionales</div><img class="figure-img" src="assets/rnf-diagrama.png" alt="Diagrama de clasificación de los requerimientos no funcionales" aria-label="Clasificación de los requerimientos no funcionales en producto, organizacionales y externos">`, note: '<strong>Desarrollo:</strong> Presentar el diagrama de clasificación de los requerimientos no funcionales: producto, organizacionales y externos; cada grupo reúne restricciones con una fuente distinta.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): rendimiento y usabilidad son del producto; la conformidad con normas internas es organizacional; la protección de datos personales es externa. Segundo contexto industrial: en salud, la confidencialidad de la historia clínica es una restricción externa impuesta por la normativa.<br><br><strong>Reflexión docente:</strong> Clasificar por origen ayuda a identificar quién impone cada restricción y quién debe verificar su cumplimiento.<br><br><strong>Pregunta desafío:</strong> ¿por qué importa saber de dónde proviene una restricción?<br><br><strong>Respuestas posibles:</strong> 1. Porque cada origen tiene responsables y plazos distintos. 2. Porque permite verificar la restricción con la fuente adecuada. 3. Porque una restricción externa puede cambiar por decisión ajena.<br><br><strong>Advertencia:</strong> la imagen esquematiza la clasificación; los ejemplos del siguiente slide la concretan.' },
  { title: 'Ejemplos de Requerimientos No Funcionales', eyebrow: '11 · Ejemplos RNF', body: `<div class="cards"><div class="card"><h3>RNF1 · Producto</h3><p>La interfaz de usuario será implementada como HTML simple sin frames ni applets Java.</p></div><div class="card"><h3>RNF2 · Organizacional</h3><p>El proceso de desarrollo y los entregables serán conformes a lo establecido en METRICA v3.</p></div><div class="card"><h3>RNF3 · Externos</h3><p>El sistema no registrará ninguna información personal de los clientes salvo su nombre y número de referencia, respetando lo establecido en la Ley Orgánica de Protección de Datos (LOPD).</p></div></div><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Tres categorías</div><div class="quote">Producto<br>Organizacionales<br>Externos</div>`, note: '<strong>Desarrollo:</strong> Recorrer los tres ejemplos: RNF1 de producto (interfaz HTML simple), RNF2 organizacional (conformidad con METRICA v3) y RNF3 externo (protección de datos según la LOPD). Mostrar cómo cada categoría se puede verificar.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): un requisito externo sería no almacenar información personal más allá del nombre y la referencia, respetando la normativa de protección de datos vigente. Segundo contexto industrial: en un sistema hospitalario, cumplir la normativa de confidencialidad es un requerimiento externo.<br><br><strong>Reflexión docente:</strong> La norma cambia según el país y el sector; los ejemplos del material usan referencias vigentes en su contexto original.<br><br><strong>Pregunta desafío:</strong> ¿cómo verificarían RNF1 (interfaz en HTML simple)?<br><br><strong>Respuestas posibles:</strong> 1. Inspeccionando el código de la interfaz. 2. Revisando que no se usen frames ni applets. 3. Ejecutando pruebas automatizadas sobre la interfaz.<br><br><strong>Advertencia:</strong> las normas citadas (METRICA, LOPD) pertenecen al contexto del material; en cada proyecto se aplica la normativa correspondiente.' },
  { title: 'Tipos de Requerimientos', eyebrow: '12 · Visión general', body: `<p>Visión general de los tipos de requerimientos y su relación dentro del sistema.</p><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Mapa de tipos de requerimientos</div><img class="figure-img" src="assets/tipos-requerimientos.jpeg" alt="Imagen que muestra los tipos de requerimientos de software" aria-label="Tipos de requerimientos de software">`, note: '<strong>Desarrollo:</strong> Presentar la imagen de los tipos de requerimientos como síntesis visual de la clasificación; relacionarla con los conceptos ya vistos de funcionales y no funcionales.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): ubicar en la imagen las capacidades de cambio de divisas (funcionales) y las restricciones de seguridad (no funcionales). Segundo contexto industrial: en logística, ubicar el rastreo de envíos (funcional) y la disponibilidad del servicio (no funcional).<br><br><strong>Reflexión docente:</strong> Una síntesis visual ayuda a retener la estructura completa antes de profundizar en la ingeniería de requerimientos.<br><br><strong>Pregunta desafío:</strong> ¿qué elemento de la imagen les resultaría más difícil de verificar?<br><br><strong>Respuestas posibles:</strong> 1. Los no funcionales, por ser transversales. 2. Los que dependen de condiciones externas. 3. Los que mezclan tipos distintos.<br><br><strong>Advertencia:</strong> la imagen resume la clasificación; los conceptos se desarrollan a lo largo de la unidad.' },
  { title: '¿Qué es la Ingeniería de Requisitos?', eyebrow: '13 · Definición', body: `<div class="card"><p><strong>"Conjunto de actividades para descubrir, documentar y mantener un conjunto de requisitos"</strong></p></div><div class="card"><p><strong>"Establecer los servicios que el cliente requiere de un sistema y las restricciones bajo las cuales opera y es desarrollado"</strong></p></div><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">La esencia</div><div class="quote">Descubrir, documentar y mantener los requisitos</div>`, note: '<strong>Desarrollo:</strong> Definir la Ingeniería de Requisitos como el conjunto de actividades para descubrir, documentar y mantener requisitos, y como el proceso de establecer los servicios que el cliente requiere y las restricciones de operación y desarrollo.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): descubrir que el cliente necesita tasas actualizadas, documentar la regla de conversión y mantenerla cuando cambie. Segundo contexto industrial: en telecomunicaciones, definir qué servicios se ofrecen y con qué restricciones de red.<br><br><strong>Reflexión docente:</strong> La palabra "mantener" es clave: los requisitos evolucionan y la Ingeniería de Requisitos los acompaña durante todo el ciclo de vida.<br><br><strong>Pregunta desafío:</strong> ¿por qué mantener es parte de la Ingeniería de Requisitos?<br><br><strong>Respuestas posibles:</strong> 1. Porque los requisitos cambian durante el ciclo de vida. 2. Porque sin mantenimiento el documento queda desactualizado. 3. Porque la gestión de cambios evita inconsistencias.<br><br><strong>Advertencia:</strong> no confundir Ingeniería de Requisitos con escribir un único documento al inicio del proyecto.' },
  { title: 'Proceso de la Ingeniería de Requerimientos', eyebrow: '14 · Definición del proceso', body: `<div class="card"><p><strong>"Conjunto estructurado de actividades de cuya ejecución se obtiene, valida y mantiene un documento de requisitos del sistema (ERS)"</strong></p></div><p>El resultado del proceso es el <strong>ERS (Especificación de Requisitos de Software)</strong>: el documento que describe qué debe hacer el sistema.</p><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010. Cap. 7.</p>`, visual: `<div class="visual-title">Fases del proceso</div><div class="process"><span>Obtención</span><span>Análisis</span><span>Especificación</span><span>Verificación</span><span>Validación</span><span>Gestión</span></div>`, note: '<strong>Desarrollo:</strong> Definir el proceso como un conjunto estructurado de actividades que obtiene, valida y mantiene el ERS; adelantar las fases que se desarrollarán: obtención, análisis, especificación, verificación, validación y gestión.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): el ERS documenta qué debe hacer el sistema de cambio de divisas y cómo se valida. Segundo contexto industrial: en banca, el ERS de un nuevo producto describe servicios, restricciones y criterios de aceptación.<br><br><strong>Reflexión docente:</strong> El proceso es estructurado, no rígido: las fases pueden retroalimentarse con nueva información.<br><br><strong>Pregunta desafío:</strong> ¿qué artefacto produce el proceso de la Ingeniería de Requerimientos?<br><br><strong>Respuestas posibles:</strong> 1. El documento de requisitos del sistema (ERS). 2. Modelos y vistas de apoyo. 3. Reportes de verificación y validación.<br><br><strong>Advertencia:</strong> el proceso no termina con el documento inicial: la gestión lo acompaña a lo largo de toda su vida.' },
  { title: 'Participantes en el Proceso', eyebrow: '15 · Participantes', body: `<p>El proceso de requerimientos reúne roles con información y controles complementarios.</p><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010. Cap. 7.</p>`, visual: `<div class="visual-title">Roles y aportes</div><div class="table-like"><div class="row"><strong>Cliente y Usuarios</strong><span>Conocen los requisitos adecuados a sus necesidades</span><b>Necesidad</b></div><div class="row"><strong>Diseñadores</strong><span>Comprenden los requerimientos para lograr un diseño que los satisfaga</span><b>Diseño</b></div><div class="row"><strong>Supervisores del Contrato</strong><span>Establecen los hitos de control y cronogramas</span><b>Control</b></div><div class="row"><strong>Gerentes del Negocio</strong><span>Entienden el impacto en la organización</span><b>Negocio</b></div><div class="row"><strong>Verificadores</strong><span>Comprenden los requerimientos para poder verificar si el sistema los satisface</span><b>Calidad</b></div></div>`, note: '<strong>Desarrollo:</strong> Presentar los cinco roles y sus aportes: cliente y usuarios (necesidades), diseñadores (diseño que los satisfaga), supervisores del contrato (hitos y cronogramas), gerentes del negocio (impacto organizacional) y verificadores (verificación del cumplimiento).<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): el cliente define las operaciones de cambio, el supervisor fija los hitos, el gerente evalúa el impacto y los verificadores prueban el cumplimiento. Segundo contexto industrial: en un proyecto gubernamental, los mismos roles se repiten con distintos interesados.<br><br><strong>Reflexión docente:</strong> Un proceso unipersonal pierde la visión de algún rol; la colaboración reduce puntos ciegos.<br><br><strong>Pregunta desafío:</strong> ¿qué pasa si un rol no participa del proceso?<br><br><strong>Respuestas posibles:</strong> 1. Se pierde la información que ese rol aporta. 2. Los requisitos pueden quedar incompletos o inconsistentes. 3. Se detectan tarde problemas de diseño, contrato o verificación.<br><br><strong>Advertencia:</strong> los roles pueden solaparse en equipos pequeños, pero las funciones deben estar cubiertas.' },
  { title: 'Proceso de la Ingeniería de Requerimientos', eyebrow: '16 · Proceso IR', body: `<p class="lede">Iniciamos el recorrido por el proceso de la Ingeniería de Requerimientos.</p><p>Un conjunto estructurado de actividades para obtener, validar y mantener el documento de requisitos del sistema (ERS).</p><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010. Cap. 7.</p>`, visual: `<div class="visual-title">Proceso de la Ingeniería de Requerimientos</div><img class="figure-img" src="assets/proceso-ir.png" alt="Diagrama del proceso de la Ingeniería de Requerimientos" aria-label="Proceso de la Ingeniería de Requerimientos">`, note: '<strong>Desarrollo:</strong> Presentar el separador que inicia el recorrido por el proceso de la Ingeniería de Requerimientos; recordar que las fases son obtención, análisis, especificación, verificación, validación y gestión.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): el proceso completo acompaña al sistema de cambio de divisas desde el relevamiento hasta su evolución. Segundo contexto industrial: en seguros, el mismo proceso define un nuevo producto de pólizas.<br><br><strong>Reflexión docente:</strong> El separador organiza la narrativa y marca dónde estamos dentro del proceso.<br><br><strong>Pregunta desafío:</strong> ¿cuál es la primera fase del proceso que veremos a continuación?<br><br><strong>Respuestas posibles:</strong> 1. La obtención de requerimientos. 2. El relevamiento de fuentes y técnicas. 3. La recolección de necesidades de los interesados.<br><br><strong>Advertencia:</strong> no confundir el separador con el contenido: la fase se desarrolla en los próximos slides.' },
  { title: 'Obtención de Requerimientos', eyebrow: '17 · Fase: Obtención', body: `<p class="lede">Primera fase del proceso: la obtención de requerimientos.</p><p>A continuación veremos las fuentes de las que se obtienen los requerimientos y las técnicas que se utilizan.</p>`, visual: `<div class="visual-title">Proceso de la Ingeniería de Requerimientos</div><img class="figure-img" src="assets/proceso-ir.png" alt="Diagrama del proceso de la Ingeniería de Requerimientos" aria-label="Proceso de la Ingeniería de Requerimientos">`, note: '<strong>Desarrollo:</strong> Anunciar la fase de obtención como la primera del proceso; a continuación veremos las fuentes y las técnicas, y luego los problemas comunes de esta fase.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): en la obtención se reúnen las necesidades de clientes, operadores y gerentes del sistema de cambio de divisas. Segundo contexto industrial: en transporte, la obtención releva necesidades de despacho, seguimiento y entrega.<br><br><strong>Reflexión docente:</strong> Obtener bien es la base: si la obtención es deficiente, el resto del proceso arrastra sus errores.<br><br><strong>Pregunta desafío:</strong> ¿de qué fuentes puede obtenerse información de requerimientos?<br><br><strong>Respuestas posibles:</strong> 1. Usuarios y clientes. 2. Sistemas existentes y documentos. 3. Modelos del dominio y sistemas análogos.<br><br><strong>Advertencia:</strong> la imagen de proceso se repite en los separadores para marcar la fase en curso.' },
  { title: 'Obtención de Requerimientos', eyebrow: '18 · Fuentes', body: `<p><strong>Fuente de los Requerimientos</strong></p><ul><li>Cliente, usuario, otros interesados (necesidades)</li><li>Modelos del dominio</li><li>Revisar la situación actual</li><li>Organización actual y sistemas</li><li>Versión actual del sistema</li><li>Desarrolladores de versión anterior</li><li>Documentos existentes (antecedentes)</li><li>Sistemas análogos ya existentes (antecedentes)</li></ul><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Grupos de fuentes</div><div class="cards"><div class="card"><h3>Necesidades</h3><p>Cliente, usuario y otros interesados</p></div><div class="card"><h3>Dominio</h3><p>Modelos del dominio y situación actual</p></div><div class="card"><h3>Sistemas</h3><p>Organización, versión actual y desarrolladores anteriores</p></div><div class="card"><h3>Antecedentes</h3><p>Documentos y sistemas análogos existentes</p></div></div>`, note: '<strong>Desarrollo:</strong> Recorrer las fuentes de requerimientos: necesidades de los interesados, modelos del dominio, revisión de la situación actual, organización y sistemas existentes, versión actual, desarrolladores anteriores, documentos y sistemas análogos.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): se relevan las necesidades de los operadores de caja, se revisa el sistema actual de tasas y los documentos de reglas de conversión. Segundo contexto industrial: en logística, se revisan los sistemas de despacho vigentes y los procesos documentados.<br><br><strong>Reflexión docente:</strong> La fuente correcta evita inventar requisitos y reduce el riesgo de omisiones.<br><br><strong>Pregunta desafío:</strong> ¿qué fuente suele olvidarse?<br><br><strong>Respuestas posibles:</strong> 1. Los sistemas análogos ya existentes. 2. Los usuarios finales, frente a los gerentes. 3. Los documentos y antecedentes históricos.<br><br><strong>Advertencia:</strong> combinar fuentes amplía la visión, pero exige conciliar las contradicciones que aparezcan.' },
  { title: 'Obtención de Requerimientos', eyebrow: '19 · Técnicas', body: `<p><strong>Técnicas de obtención</strong></p><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010. Cap. 7.</p>`, visual: `<div class="visual-title">Cuatro técnicas</div><div class="process"><span>Reuniones / Entrevistas</span><span>Cuestionarios</span><span>Observación</span><span>Brainstorming</span></div>`, note: '<strong>Desarrollo:</strong> Presentar las cuatro técnicas de obtención: reuniones y entrevistas, cuestionarios, observación y brainstorming; cada una sirve a un propósito distinto.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): entrevistas a operadores para conocer el flujo de una venta de divisas, observación del trabajo de caja y brainstorming de reglas de conversión. Segundo contexto industrial: en salud, entrevistas a médicos y observación de turnos para relevar necesidades.<br><br><strong>Reflexión docente:</strong> La técnica se elige según el tipo de información que se busca y las personas involucradas.<br><br><strong>Pregunta desafío:</strong> ¿cuándo conviene un cuestionario en lugar de una entrevista?<br><br><strong>Respuestas posibles:</strong> 1. Con muchas personas y preguntas cerradas. 2. Cuando se quiere estandarizar la recolección. 3. Cuando el tiempo para entrevistas individuales es limitado.<br><br><strong>Advertencia:</strong> la observación complementa lo que se declara: lo que se dice no siempre coincide con lo que se hace.' },
  { title: 'Obtención de Requerimientos', eyebrow: '20 · Problemas comunes', body: `<ul><li>No saben lo que quieren del sistema, sólo en términos generales; no conocen el costo de sus peticiones.</li><li>Los requisitos están en sus términos y con conocimiento implícito de su propio trabajo.</li><li>Distintos usuarios tienen distintos requisitos; se deben encontrar todas las fuentes.</li><li>Influyen factores políticos.</li><li>La prioridad que se da a los requisitos varía con el tiempo.</li><li>Aparecen nuevos requisitos.</li></ul><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Barreras de la obtención</div><div class="quote">Necesidades imprecisas<br>Conocimiento implícito<br>Requisitos en conflicto<br>Factores políticos<br>Prioridades cambiantes</div>`, note: '<strong>Desarrollo:</strong> Analizar los problemas típicos de la obtención: usuarios que no saben lo que quieren, conocimiento implícito, requisitos en conflicto entre usuarios, factores políticos, prioridades cambiantes y aparición de nuevos requisitos.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): operadores y gerentes pueden pedir reglas de conversión distintas, y la prioridad entre seguridad y velocidad puede variar. Segundo contexto industrial: en gobierno, distintas dependencias pueden tener requisitos en conflicto.<br><br><strong>Reflexión docente:</strong> Reconocer los problemas es el primer paso para gestionarlos dentro del proceso.<br><br><strong>Pregunta desafío:</strong> ¿qué problema de la lista consideran más difícil de resolver?<br><br><strong>Respuestas posibles:</strong> 1. El conocimiento implícito del propio trabajo. 2. Los requisitos en conflicto entre usuarios. 3. La aparición de nuevos requisitos durante el proceso.<br><br><strong>Advertencia:</strong> los problemas no se eliminan por completo; se gestionan con técnicas, negociación y trazabilidad.' },
  { title: 'Proceso de la Ingeniería de Requerimientos', eyebrow: '21 · Proceso IR', body: `<p class="lede">Finalizada la obtención, la siguiente fase del proceso es el análisis de requerimientos.</p><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010. Cap. 7.</p>`, visual: `<div class="visual-title">Proceso de la Ingeniería de Requerimientos</div><img class="figure-img" src="assets/proceso-ir.png" alt="Diagrama del proceso de la Ingeniería de Requerimientos" aria-label="Proceso de la Ingeniería de Requerimientos">`, note: '<strong>Desarrollo:</strong> Marcar el avance del proceso: finalizada la obtención, la siguiente fase es el análisis de requerimientos.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): las necesidades relevadas pasan a analizarse y modelarse antes de especificarse. Segundo contexto industrial: en banca, los requisitos relevados se analizan antes de redactar el documento.<br><br><strong>Reflexión docente:</strong> Cada separador recuerda que el proceso avanza de fase en fase.<br><br><strong>Pregunta desafío:</strong> ¿qué se hace con lo obtenido en la fase de análisis?<br><br><strong>Respuestas posibles:</strong> 1. Se analiza y modela la información. 2. Se negocian prioridades. 3. Se buscan requerimientos que faltan.<br><br><strong>Advertencia:</strong> la fase de análisis se detalla en los próximos slides.' },
  { title: 'Análisis de Requerimientos', eyebrow: '22 · Análisis', body: `<ul><li>Analizar stakeholders / clientes / usuarios</li><li>Crear vistas</li><li>Detallar</li><li>Negociar prioridades</li><li>Buscar requerimientos que faltan</li><li>Evaluar factibilidad técnica – prototipos</li><li>Evaluar riesgos de requerimientos</li></ul><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010. Cap. 7.</p>`, visual: `<div class="visual-title">Tareas del análisis</div><div class="cards"><div class="card"><h3>Personas</h3><p>Analizar stakeholders, clientes y usuarios</p></div><div class="card"><h3>Vistas</h3><p>Crear y detallar vistas del sistema</p></div><div class="card"><h3>Prioridades</h3><p>Negociar y ordenar requerimientos</p></div><div class="card"><h3>Cobertura</h3><p>Buscar requerimientos que faltan</p></div><div class="card"><h3>Factibilidad</h3><p>Evaluar con prototipos</p></div><div class="card"><h3>Riesgo</h3><p>Evaluar riesgos de requerimientos</p></div></div>`, note: '<strong>Desarrollo:</strong> Presentar las tareas del análisis: analizar los interesados, crear vistas, detallar, negociar prioridades, buscar requerimientos faltantes, evaluar la factibilidad con prototipos y evaluar riesgos.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): se detallan las operaciones de cambio, se negocia la prioridad entre funciones y se prueba la factibilidad con un prototipo de la interfaz de operación. Segundo contexto industrial: en telecomunicaciones, se evalúa la factibilidad técnica de nuevas funcionalidades.<br><br><strong>Reflexión docente:</strong> El análisis convierte necesidades en algo modelable y negociable.<br><br><strong>Pregunta desafío:</strong> ¿para qué sirven los prototipos en el análisis?<br><br><strong>Respuestas posibles:</strong> 1. Para evaluar la factibilidad técnica. 2. Para aclarar necesidades con el usuario. 3. Para detectar requerimientos faltantes.<br><br><strong>Advertencia:</strong> analizar no es codificar: los modelos se usan para entender, no para entregar.' },
  { title: 'Análisis de Requerimientos', eyebrow: '23 · Modelos o vistas', body: `<p><strong>Modelos o Vistas del Sistema</strong></p><ul><li>Glosario</li><li>Modelos gráficos</li><li>Modelo conceptual</li><li>Diagramas de estado – para entidades complejas que pasen por distintos estados</li><li>Diagramas de Flujo de Datos (DFD)</li><li>Prototipos de interfaz gráfica</li><li>Casos de Prueba</li><li>Tablas de Decisión</li><li>Casos de Uso</li></ul><p class="reference">SWEBOK Guide. IEEE Computer Society.</p>`, visual: `<div class="visual-title">Vistas complementarias</div><div class="cards"><div class="card"><h3>Texto</h3><p>Glosario y casos de prueba</p></div><div class="card"><h3>Gráficos</h3><p>Modelos conceptuales, estados y DFD</p></div><div class="card"><h3>Interfaz</h3><p>Prototipos de interfaz gráfica</p></div><div class="card"><h3>Reglas</h3><p>Tablas de decisión</p></div><div class="card"><h3>Comportamiento</h3><p>Casos de uso</p></div></div>`, note: '<strong>Desarrollo:</strong> Presentar los modelos y vistas del sistema: glosario, modelos gráficos, modelo conceptual, diagramas de estado, DFD, prototipos de interfaz, casos de prueba, tablas de decisión y casos de uso.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): un diagrama de estados modela los estados de una operación de cambio y un caso de uso describe la venta de divisas. Segundo contexto industrial: en logística, un DFD describe el flujo de un pedido.<br><br><strong>Reflexión docente:</strong> Cada vista ilumina un aspecto del sistema; varias vistas complementarias reducen la ambigüedad.<br><br><strong>Pregunta desafío:</strong> ¿qué vista usarían para entidades que pasan por distintos estados?<br><br><strong>Respuestas posibles:</strong> 1. Diagramas de estados. 2. Diagramas de flujo de datos. 3. Casos de uso o tablas de decisión.<br><br><strong>Advertencia:</strong> no confundir las vistas de análisis con los artefactos de diseño que se crean en etapas posteriores.' },
  { title: 'Proceso de la Ingeniería de Requerimientos', eyebrow: '24 · Proceso IR', body: `<p class="lede">Completado el análisis, la siguiente fase del proceso es la especificación de los requerimientos.</p><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010. Cap. 7.</p>`, visual: `<div class="visual-title">Proceso de la Ingeniería de Requerimientos</div><img class="figure-img" src="assets/proceso-ir.png" alt="Diagrama del proceso de la Ingeniería de Requerimientos" aria-label="Proceso de la Ingeniería de Requerimientos">`, note: '<strong>Desarrollo:</strong> Marcar el avance del proceso: completado el análisis, la siguiente fase es la especificación de los requerimientos.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): los modelos analizados se convierten en el documento de especificación. Segundo contexto industrial: en seguros, la especificación formaliza los requisitos de la nueva póliza.<br><br><strong>Reflexión docente:</strong> La especificación traduce los modelos en un documento formal y comprensible.<br><br><strong>Pregunta desafío:</strong> ¿qué documento produce la fase de especificación?<br><br><strong>Respuestas posibles:</strong> 1. El ERS o SRS. 2. El documento formal de requisitos. 3. La especificación de requisitos de software.<br><br><strong>Advertencia:</strong> la fase de especificación se desarrolla en los próximos slides.' },
  { title: 'Especificación de Requerimientos', eyebrow: '25 · Especificación', body: `<p><strong>Documentación de requisitos</strong></p><p><strong>Qué documentar:</strong></p><ul><li>lo que hace el sistema actual</li><li>lo que el cliente pide</li><li>lo que el sistema va a hacer</li><li>criterios de aceptación</li><li>criterios de verificación</li></ul><p><strong>Recomendaciones:</strong></p><ul><li>agrupar por temas</li><li>formular los requerimientos como positivos y no negativos</li><li>expresarlos en voz activa y no pasiva</li><li>indicar si se documenta solo lo que va en el alcance o todo lo que se pidió</li><li>representar requerimientos con múltiples vistas</li></ul><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010. Cap. 7.</p>`, visual: `<div class="visual-title">Documentar bien</div><div class="quote">Qué se documenta y cómo se formula determina la calidad de la especificación</div>`, note: '<strong>Desarrollo:</strong> Explicar qué documentar (lo que hace el sistema actual, lo que pide el cliente, lo que hará el sistema, criterios de aceptación y verificación) y las recomendaciones de redacción: agrupar por temas, formulación positiva, voz activa, alcance claro y múltiples vistas.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): el documento describe las operaciones actuales de caja, lo que pide el cliente y cómo se verificará la conversión. Segundo contexto industrial: en logística, la especificación documenta el flujo de envíos y sus criterios de aceptación.<br><br><strong>Reflexión docente:</strong> La redacción del documento determina su utilidad para clientes y desarrolladores.<br><br><strong>Pregunta desafío:</strong> ¿por qué se recomienda formular los requerimientos en voz activa y en forma positiva?<br><br><strong>Respuestas posibles:</strong> 1. Para evitar ambigüedad sobre quién ejecuta la acción. 2. Para facilitar la verificación. 3. Para reducir interpretaciones dobles.<br><br><strong>Advertencia:</strong> documentar "todo lo que se pidió" no es lo mismo que documentar solo lo que entra en el alcance.' },
  { title: 'Especificación de Requerimientos', eyebrow: '26 · Documento', body: `<p><strong>Documento de Especificación de Requisitos</strong></p><ul><li>Registrar los requisitos en los términos del cliente</li><li>Delinear el propósito general del sistema: incluir referencias a otros sistemas, glosario y abreviaciones</li><li>Describir el contexto y objetivos del desarrollo del sistema</li><li>Delinear visión global del sistema: incluir restricciones generales</li><li>Definir en detalle las características del sistema propuesto, el alcance del sistema e interfaces</li><li>Discutir el ambiente en el que el sistema va a operar (hardware, comunicaciones, personal)</li></ul><p class="reference">IEEE Std 830-1998. IEEE Recommended Practice for Software Requirements Specifications. IEEE.</p>`, visual: `<div class="visual-title">Contenido del documento</div><div class="cards"><div class="card"><h3>Propósito</h3><p>Terminología del cliente, referencias, glosario</p></div><div class="card"><h3>Contexto</h3><p>Objetivos y visión global del sistema</p></div><div class="card"><h3>Detalle</h3><p>Características, alcance e interfaces</p></div><div class="card"><h3>Ambiente</h3><p>Hardware, comunicaciones y personal</p></div></div>`, note: '<strong>Desarrollo:</strong> Presentar el contenido del documento de especificación: requisitos en los términos del cliente, propósito general con referencias y glosario, contexto y objetivos, visión global con restricciones, características y alcance con interfaces, y ambiente de operación.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): el documento define el propósito del sistema de cambio, su alcance, las interfaces con el servicio de tasas y el ambiente de operación. Segundo contexto industrial: en banca, el documento describe el ambiente de hardware y comunicaciones del nuevo producto.<br><br><strong>Reflexión docente:</strong> El documento es el contrato de entendimiento entre el cliente y el equipo de desarrollo.<br><br><strong>Pregunta desafío:</strong> ¿por qué registrar los requisitos en los términos del cliente?<br><br><strong>Respuestas posibles:</strong> 1. Para que el cliente pueda validar el documento. 2. Para reducir malentendidos. 3. Para que todos los involucrados lo comprendan.<br><br><strong>Advertencia:</strong> el glosario y las referencias son parte del documento, no un accesorio.' },
  { title: 'Especificación de Requerimientos', eyebrow: '27 · SRS IEEE 830', body: `<p><strong>Características de una Buena Especificación SRS (IEEE 830)</strong></p><div class="card"><h3>Correcta / Válida</h3><p>Todos los requerimientos son requeridos en el sistema. No existe herramienta que asegure esto: debe ser validada por el cliente (que efectivamente refleje sus necesidades).</p></div><div class="card"><h3>No Ambigua</h3><p>Todo requerimiento tiene una única interpretación. Incluir glosario; debe ser no ambigua para quienes la crearon y para quienes la usan.</p></div><p class="reference">IEEE Std 830-1998. IEEE Recommended Practice for Software Requirements Specifications. IEEE.</p>`, visual: `<div class="visual-title">Completa</div><div class="card"><p>Debe incluir:</p><ul><li>Todos los requisitos asociados con funcionalidad, desempeño, restricciones de diseño, atributos o interfaces externas.</li><li>Definición de respuestas del software a todo posible dato de entrada (válido o inválido) en toda clase de situaciones realizables.</li><li>No hay referencias sin definir en la especificación.</li></ul><p>La frase "a determinar" indica que la SRS no está completa. Si es ocasionalmente necesaria, describir: condiciones que causan que no se sepa aún y qué se debe hacer para determinar lo que falta, con quién y cuándo.</p></div>`, note: '<strong>Desarrollo:</strong> Presentar las características de una buena SRS según IEEE 830: correcta o válida, no ambigua y completa, con sus implicancias.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): la SRS debe ser validada por el cliente (correcta), cada regla de conversión con una única interpretación (no ambigua) y sin "a determinar" sin explicación (completa). Segundo contexto industrial: en gobierno, una SRS incompleta genera retrabajo en los procesos de licitación.<br><br><strong>Reflexión docente:</strong> La completitud es difícil de demostrar; la frase "a determinar" es una señal de alerta en la especificación.<br><br><strong>Pregunta desafío:</strong> ¿qué indica la frase "a determinar" en una SRS?<br><br><strong>Respuestas posibles:</strong> 1. Que la SRS no está completa. 2. Que aún falta decidir algo. 3. Que hay que describir las condiciones y los responsables para resolverlo.<br><br><strong>Advertencia:</strong> la completitud absoluta no existe; la norma exige explicitar qué falta y cómo se resolverá.' },
  { title: 'Especificación de Requerimientos', eyebrow: '28 · SRS IEEE 830', body: `<div class="card"><h3>Consistente internamente</h3><p>Los requisitos no son contradictorios entre sí.</p></div><div class="card"><h3>Ordenada por grado de importancia y/o estabilidad</h3><p>Los requisitos deben tener un identificador.</p></div><p class="reference">IEEE Std 830-1998. IEEE Recommended Practice for Software Requirements Specifications. IEEE.</p>`, visual: `<div class="visual-title">Verificable</div><div class="card"><p>Un requerimiento es verificable si existe un proceso finito de costo accesible para determinar que el sistema lo cumple.</p><ul><li>Usar términos concretos y cantidades mesurables.</li><li>Preparar pruebas para demostrar que se cumplen. Si no se puede, eliminar o revisar el requisito.</li><li>Expresar cada requerimiento por separado.</li></ul></div>`, note: '<strong>Desarrollo:</strong> Continuar con las características de la SRS según IEEE 830: consistencia interna, orden por importancia y estabilidad con identificador, y verificabilidad.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): dos reglas de conversión que se contradicen son una inconsistencia; cada requerimiento debe tener identificador y pruebas de verificación. Segundo contexto industrial: en transporte, los requerimientos contradictorios de rutas se detectan en la revisión.<br><br><strong>Reflexión docente:</strong> La verificabilidad obliga a usar términos concretos y cantidades mesurables.<br><br><strong>Pregunta desafío:</strong> ¿qué hacer con un requerimiento que no se puede verificar?<br><br><strong>Respuestas posibles:</strong> 1. Revisarlo o eliminarlo. 2. Reformularlo con términos medibles. 3. Preparar pruebas para demostrar su cumplimiento.<br><br><strong>Advertencia:</strong> el identificador único es la base de la trazabilidad posterior.' },
  { title: 'Especificación de Requerimientos', eyebrow: '29 · SRS IEEE 830', body: `<div class="card"><h3>Trazable</h3><p>El origen de cada requerimiento es claro, y es posible seguirle la pista en futuros desarrollos o mejora de la documentación.</p><ul><li>Trazabilidad hacia atrás: en versiones previas.</li><li>Trazabilidad hacia adelante: documentos posteriores.</li><li>Requiere IDENTIFICADOR ÚNICO.</li></ul></div><div class="card"><h3>Realista / Factible</h3><p>Ej.: tiempo de respuesta local = remoto. Ej.: el cliente quiere adelantarse a la tecnología.</p></div><p class="reference">IEEE Std 830-1998. IEEE Recommended Practice for Software Requirements Specifications. IEEE.</p>`, visual: `<div class="visual-title">Entendible</div><div class="quote">Tanto por los usuarios como por los desarrolladores</div>`, note: '<strong>Desarrollo:</strong> Completar las características de la SRS: trazabilidad (hacia atrás y hacia adelante, con identificador único), realismo o factibilidad y entendibilidad.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): cada requisito debe rastrearse desde su origen hasta los documentos posteriores; un requisito de respuesta instantánea debe ser realista con la tecnología disponible. Segundo contexto industrial: en telecomunicaciones, exigir tecnología futura puede volver irreal el requisito.<br><br><strong>Reflexión docente:</strong> Trazabilidad, realismo y entendibilidad protegen el documento durante toda su vida útil.<br><br><strong>Pregunta desafío:</strong> ¿qué se necesita para lograr la trazabilidad?<br><br><strong>Respuestas posibles:</strong> 1. Identificador único por requerimiento. 2. Registro del origen. 3. Vínculos con documentos posteriores.<br><br><strong>Advertencia:</strong> "adelantarse a la tecnología" puede generar requisitos irrealizables dentro del plazo del proyecto.' },
  { title: 'Proceso de la Ingeniería de Requerimientos', eyebrow: '30 · Proceso IR', body: `<p class="lede">Concluida la especificación, la siguiente fase del proceso es la verificación de los requerimientos.</p><p class="reference">SWEBOK Guide. IEEE Computer Society.</p>`, visual: `<div class="visual-title">Proceso de la Ingeniería de Requerimientos</div><img class="figure-img" src="assets/proceso-ir.png" alt="Diagrama del proceso de la Ingeniería de Requerimientos" aria-label="Proceso de la Ingeniería de Requerimientos">`, note: '<strong>Desarrollo:</strong> Marcar el avance del proceso: concluida la especificación, la siguiente fase es la verificación de los requerimientos.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): el documento especificado se verifica antes de validarlo con el cliente. Segundo contexto industrial: en banca, la verificación revisa el documento internamente.<br><br><strong>Reflexión docente:</strong> La verificación revisa el documento; la validación revisa contra las necesidades del cliente. Son dos controles distintos.<br><br><strong>Pregunta desafío:</strong> ¿en qué se diferencia la verificación de la validación?<br><br><strong>Respuestas posibles:</strong> 1. La verificación revisa el documento; la validación revisa contra el cliente. 2. La verificación busca defectos internos. 3. La validación confirma que la especificación responde a las necesidades.<br><br><strong>Advertencia:</strong> la fase de verificación se desarrolla en los próximos slides.' },
  { title: 'Verificación de Requerimientos', eyebrow: '31 · Verificación', body: `<p>Se verifica en el documento de requisitos:</p><ul><li><strong>Consistencia:</strong> que no haya contradicciones.</li><li><strong>Completitud:</strong> que no falte nada. Chequear por omisiones (árboles de decisión para ver que estén todas las opciones detalladas) y por límites (una tabla permite ver que no falta ninguno).</li><li><strong>Ambigüedades</strong></li><li><strong>Realismo o Factibilidad:</strong> que se puedan implementar con la tecnología, presupuesto y calendario existentes.</li><li><strong>Verificabilidad:</strong> que se pueda diseñar un conjunto de pruebas para demostrar que el sistema cumple esos requisitos. Cuidado con adjetivos y adverbios.</li><li><strong>Comprensibilidad:</strong> que los usuarios finales lo entiendan.</li><li><strong>Adaptabilidad:</strong> que el requisito se pueda cambiar sin afectar a otros.</li><li><strong>Trazabilidad:</strong> que esté establecido el origen.</li></ul><p class="reference">SWEBOK Guide. IEEE Computer Society.</p>`, visual: `<div class="visual-title">Dimensiones de la verificación</div><div class="cards"><div class="card"><h3>Consistencia</h3><p>Sin contradicciones</p></div><div class="card"><h3>Completitud</h3><p>Sin omisiones ni límites faltantes</p></div><div class="card"><h3>Ambigüedad</h3><p>Sin interpretaciones dobles</p></div><div class="card"><h3>Realismo</h3><p>Implementable con los recursos actuales</p></div><div class="card"><h3>Verificabilidad</h3><p>Pruebas diseñables</p></div><div class="card"><h3>Comprensibilidad</h3><p>Entendible por los usuarios</p></div><div class="card"><h3>Adaptabilidad</h3><p>Cambiable sin romper otros</p></div><div class="card"><h3>Trazabilidad</h3><p>Origen establecido</p></div></div>`, note: '<strong>Desarrollo:</strong> Recorrer las dimensiones de la verificación en el documento: consistencia, completitud (omisiones y límites), ambigüedad, realismo o factibilidad, verificabilidad, comprensibilidad, adaptabilidad y trazabilidad.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): se verifica que no haya reglas contradictorias, que los límites de las tasas estén completos en una tabla y que los adjetivos no generen ambigüedad. Segundo contexto industrial: en logística, se verifica que no falten casos límite de entrega.<br><br><strong>Reflexión docente:</strong> Cuidar adjetivos y adverbios evita requerimientos inverificables.<br><br><strong>Pregunta desafío:</strong> ¿por qué los árboles de decisión ayudan a la completitud?<br><br><strong>Respuestas posibles:</strong> 1. Porque permiten ver todas las opciones detalladas. 2. Porque muestran las omisiones. 3. Porque estructuran los casos límite.<br><br><strong>Advertencia:</strong> la verificación interna no sustituye la validación con el cliente.' },
  { title: 'Verificación de Requerimientos', eyebrow: '32 · Verificación de RNF', body: `<p><strong>Verificación de los Requerimientos NO funcionales</strong></p><ul><li>Son difíciles de verificar.</li><li>Se deben expresar de manera cuantitativa utilizando métricas que se puedan probar de forma objetiva (esto es IDEAL).</li><li>Para los usuarios es difícil especificarlos en forma cuantitativa.</li></ul><p class="reference">SWEBOK Guide. IEEE Computer Society.</p>`, visual: `<div class="visual-title">Verificación de los requerimientos no funcionales</div><img class="figure-img" src="assets/verificacion-rnf.png" alt="Diagrama de verificación de los requerimientos no funcionales" aria-label="Verificación de los requerimientos no funcionales">`, note: '<strong>Desarrollo:</strong> Explicar que los requerimientos no funcionales son difíciles de verificar y que se deben expresar cuantitativamente con métricas objetivas; reconocer que a los usuarios les cuesta especificarlos de esa forma.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): "el sistema debe responder en menos de 2 segundos" es verificable; "debe ser rápido" no lo es. Segundo contexto industrial: en salud, "el sistema debe estar disponible el 99,9% del tiempo" es una métrica verificable.<br><br><strong>Reflexión docente:</strong> La cuantificación es el ideal; el equipo debe acompañar al usuario para lograrla.<br><br><strong>Pregunta desafío:</strong> ¿cómo reformularían "el sistema debe ser seguro"?<br><br><strong>Respuestas posibles:</strong> 1. Con métricas de seguridad específicas. 2. Con criterios de control de acceso verificables. 3. Con pruebas de vulnerabilidad definidas.<br><br><strong>Advertencia:</strong> sin métricas, un requerimiento no funcional no se puede aceptar de forma objetiva.' },
  { title: 'Proceso de la Ingeniería de Requerimientos', eyebrow: '33 · Proceso IR', body: `<p class="lede">Verificada la especificación, la siguiente fase del proceso es la validación de los requerimientos.</p><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010. Cap. 7.</p>`, visual: `<div class="visual-title">Proceso de la Ingeniería de Requerimientos</div><img class="figure-img" src="assets/proceso-ir.png" alt="Diagrama del proceso de la Ingeniería de Requerimientos" aria-label="Proceso de la Ingeniería de Requerimientos">`, note: '<strong>Desarrollo:</strong> Marcar el avance del proceso: verificada la especificación, la siguiente fase es la validación de los requerimientos.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): tras la verificación interna, el documento se valida con el cliente. Segundo contexto industrial: en seguros, la validación confirma que el documento refleja las necesidades del negocio.<br><br><strong>Reflexión docente:</strong> Verificación y validación forman el control de calidad del proceso de requerimientos.<br><br><strong>Pregunta desafío:</strong> ¿quién participa principalmente en la validación?<br><br><strong>Respuestas posibles:</strong> 1. El cliente y los usuarios. 2. Los representantes de las necesidades. 3. Los interesados que validan el documento.<br><br><strong>Advertencia:</strong> la fase de validación se desarrolla en los próximos slides.' },
  { title: 'Validación de Requerimientos', eyebrow: '34 · Validación', body: `<p><strong>Proceso por el cual se determina si la especificación es consistente con las necesidades del cliente.</strong></p><p>Se verifica en el documento de requisitos:</p><ul><li><strong>Validez:</strong> que el usuario valide qué es lo que quiere.</li><li>Planificar quién (qué stakeholder) va a validar qué artefacto y cómo (técnica).</li><li>Registrar – Reporte de validación / Firma.</li></ul><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010. Cap. 7.</p>`, visual: `<div class="visual-title">La clave</div><div class="quote">La especificación es consistente con las necesidades del cliente</div>`, note: '<strong>Desarrollo:</strong> Definir la validación como el proceso de determinar si la especificación es consistente con las necesidades del cliente; verificar la validez, planificar quién valida qué y cómo, y registrar con reporte y firma.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): el cliente valida que las operaciones de cambio especificadas son las que necesita y firma el reporte. Segundo contexto industrial: en gobierno, la validación formal confirma el alcance del sistema.<br><br><strong>Reflexión docente:</strong> La firma hace visible la aceptación y fija un punto de referencia para los cambios posteriores.<br><br><strong>Pregunta desafío:</strong> ¿qué registra un reporte de validación?<br><br><strong>Respuestas posibles:</strong> 1. Qué artefacto se validó y con qué técnica. 2. Quién lo validó. 3. El resultado y la firma.<br><br><strong>Advertencia:</strong> validar no es aprobar sin revisar: exige comparar el documento contra las necesidades reales.' },
  { title: 'Validación de Requerimientos', eyebrow: '35 · Proceso manual', body: `<p><strong>Proceso manual:</strong> se revisa el documento de requisitos buscando anomalías y omisiones.</p><ul><li><strong>Revisiones informales:</strong> discusión informal.</li><li><strong>Revisiones formales:</strong> se hace una "recorrida" del documento de requisitos con el cliente, explicando implicancias de cada requisito.</li></ul><p><strong>Participan representantes:</strong></p><ul><li>del <strong>cliente</strong>: operadores, quienes realicen entradas, utilicen salidas, y sus gerentes.</li><li>del <strong>equipo de desarrollo</strong>: analistas de requisitos, diseñadores, encargados de pruebas y gestión de configuración.</li></ul><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010. Cap. 7.</p>`, visual: `<div class="visual-title">Revisión</div><div class="cards"><div class="card"><h3>Incluye</h3><ul><li>Revisar objetivos del sistema</li><li>Evaluar alineamiento de requisitos con los objetivos (necesidad)</li><li>Revisar el ambiente de operación y las interfaces con otros sistemas</li><li>Funciones completas, restricciones realistas</li><li>Evaluar riesgos</li></ul></div><div class="card"><h3>Considerar</h3><ul><li>Pruebas del sistema</li><li>Cambios en los requisitos del proyecto, su verificación y validación</li></ul></div></div>`, note: '<strong>Desarrollo:</strong> Explicar el proceso manual de validación: revisiones informales y formales (recorrida del documento con el cliente), con representantes del cliente y del equipo de desarrollo; incluye revisar objetivos, alineamiento, ambiente, funciones, restricciones y riesgos, y considerar pruebas y cambios.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): una recorrida del documento con operadores y gerentes explica las implicancias de cada regla de conversión. Segundo contexto industrial: en logística, la recorrida revisa rutas, entregas y excepciones.<br><br><strong>Reflexión docente:</strong> La revisión formal es costosa, pero detecta errores antes de construir.<br><br><strong>Pregunta desafío:</strong> ¿qué papel juegan los operadores en la recorrida?<br><br><strong>Respuestas posibles:</strong> 1. Validar que las entradas y salidas sean las correctas. 2. Confirmar que el flujo coincide con el trabajo real. 3. Detectar omisiones de funciones.<br><br><strong>Advertencia:</strong> una recorrida superficial no reemplaza la revisión de las implicancias de cada requisito.' },
  { title: 'Gestión de Requerimientos', eyebrow: '36 · Gestión', body: `<p><strong>Proceso de comprender y controlar los cambios en los requisitos del sistema.</strong></p><p>Se hace en paralelo con el Proceso de Requisitos.</p><p><strong>Los requisitos cambian, debido a:</strong></p><ul><li>Muchos usuarios</li><li>Quienes pagan por el sistema y los usuarios no son las mismas personas</li><li>Cambios en el negocio</li><li>Cambios en la tecnología</li></ul><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Tres etapas</div><div class="sequence-card" aria-label="Etapas de la gestión de requerimientos"><div class="sequence-step"><span class="sequence-index">01</span><strong>Planificación</strong><small>Al comenzar el análisis</small></div><div class="sequence-step"><span class="sequence-index">02</span><strong>Administración del cambio</strong><small>Con la primera versión del documento</small></div><div class="sequence-step"><span class="sequence-index">03</span><strong>Trazabilidad</strong><small>A lo largo del proceso</small></div></div>`, note: '<strong>Desarrollo:</strong> Definir la gestión de requerimientos como el proceso de comprender y controlar los cambios; se hace en paralelo con el proceso de requisitos. Explicar por qué cambian (muchos usuarios, pagadores distintos de los usuarios, cambios en el negocio y en la tecnología) y las tres etapas: planificación, administración del cambio y trazabilidad.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): una nueva normativa de cambios exige actualizar un requisito y su impacto debe controlarse con el proceso de gestión. Segundo contexto industrial: en banca, el cambio de tasas o de normativa dispara la administración del cambio.<br><br><strong>Reflexión docente:</strong> El cambio es inevitable; la gestión lo convierte en un proceso controlado.<br><br><strong>Pregunta desafío:</strong> ¿cuándo comienza la administración del cambio?<br><br><strong>Respuestas posibles:</strong> 1. Cuando existe una primera versión del documento de requisitos. 2. Tras la planificación. 3. Cuando aparece el primer cambio.<br><br><strong>Advertencia:</strong> sin gestión, cada cambio nuevo puede romper el alcance y el plan del proyecto.' },
  { title: 'Gestión de Requerimientos — Herramientas', eyebrow: '37 · Herramientas', body: `<p class="lede">Herramientas de apoyo para la gestión de requerimientos:</p><div class="cards"><div class="card"><h3>JIRA</h3><p>Gestión de proyectos con historias de usuario, tareas, epics, prioridades, seguimiento de estado y colaboración en equipo.</p></div><div class="card"><h3>Trello</h3><p>Tableros visuales con tarjetas para requerimientos, listas para organizarlos y tableros para el flujo de trabajo.</p></div><div class="card"><h3>Confluence</h3><p>Documentación estructurada: especificaciones de requerimientos, casos de uso y otros artefactos.</p></div><div class="card"><h3>GitHub Issues</h3><p>Seguimiento de problemas, bugs y mejoras integrado en GitHub, utilizable para gestionar requerimientos.</p></div></div><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 4.</p>`, visual: `<div class="visual-title">Cuatro herramientas</div><div class="quote">JIRA<br>Trello<br>Confluence<br>GitHub Issues</div>`, note: '<strong>Desarrollo:</strong> Presentar herramientas de apoyo: JIRA, Trello, Confluence y GitHub Issues, con sus funciones para la gestión de requerimientos.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): se pueden registrar historias de usuario de las operaciones de cambio en JIRA y documentar la especificación en Confluence. Segundo contexto industrial: en telecomunicaciones, los tableros de Trello organizan el flujo de requerimientos.<br><br><strong>Reflexión docente:</strong> La herramienta apoya el proceso; no reemplaza la disciplina de gestión.<br><br><strong>Pregunta desafío:</strong> ¿qué aporta un tablero visual a la gestión?<br><br><strong>Respuestas posibles:</strong> 1. Visibilidad del flujo de trabajo. 2. Seguimiento del estado. 3. Colaboración del equipo.<br><br><strong>Advertencia:</strong> los nombres de herramientas son ejemplos del material; cada organización elige según su contexto.' },
  { title: 'Ejemplos', eyebrow: '38 · Enlaces de consulta', body: `<p>Ejemplos de requerimientos funcionales y no funcionales para consulta:</p><ul><li><a href="http://www.pmoinformatica.com/2017/02/requerimientos-funcionales-ejemplos.html">Requerimientos funcionales – ejemplos (pmoinformatica.com)</a></li><li><a href="http://www.pmoinformatica.com/2015/05/requerimientos-no-funcionales-ejemplos.html">Requerimientos no funcionales – ejemplos (pmoinformatica.com)</a></li></ul>`, visual: `<div class="visual-title">Recursos</div><div class="cards"><div class="card"><h3>Requerimientos funcionales</h3><p><a href="http://www.pmoinformatica.com/2017/02/requerimientos-funcionales-ejemplos.html">http://www.pmoinformatica.com/2017/02/requerimientos-funcionales-ejemplos.html</a></p></div><div class="card"><h3>Requerimientos no funcionales</h3><p><a href="http://www.pmoinformatica.com/2015/05/requerimientos-no-funcionales-ejemplos.html">http://www.pmoinformatica.com/2015/05/requerimientos-no-funcionales-ejemplos.html</a></p></div></div>`, note: '<strong>Desarrollo:</strong> Presentar enlaces de consulta con ejemplos de requerimientos funcionales y no funcionales; usarlos como material complementario.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): los ejemplos de los enlaces pueden adaptarse para ilustrar requisitos del sistema de cambio de divisas. Segundo contexto industrial: los mismos patrones de formulación aplican a otros sectores.<br><br><strong>Reflexión docente:</strong> Los recursos externos complementan; la bibliografía del curso sigue siendo la referencia principal.<br><br><strong>Pregunta desafío:</strong> ¿cómo usarían los ejemplos de los enlaces en un proyecto?<br><br><strong>Respuestas posibles:</strong> 1. Como referencia de formulación. 2. Como inspiración para adaptar a su contexto. 3. Como fuente de patrones verificables.<br><br><strong>Advertencia:</strong> los enlaces son recursos complementarios del material original; pueden cambiar con el tiempo.' },
  { title: 'Muchas gracias', eyebrow: '39 · Cierre', body: `<p class="lede">Muchas gracias por su atención.</p><p>Los requerimientos son la base de un sistema exitoso: obtenerlos, analizarlos, especificarlos, verificarlos, validarlos y gestionarlos define el primer gran trabajo del ingeniero de software.</p>`, visual: `<div class="visual-title">Síntesis</div><p>Un sistema exitoso comienza con requerimientos claros, verificables y gestionados.</p>`, note: '<strong>Desarrollo:</strong> Cerrar la unidad retomando el recorrido: desde qué es un requerimiento hasta su gestión, con el proceso de la Ingeniería de Requerimientos como hilo conductor.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): aplicar el proceso completo al sistema de cambio de divisas demuestra el valor de la disciplina. Segundo contexto industrial: cualquier sistema (salud, banca, logística) depende de los mismos principios.<br><br><strong>Reflexión docente:</strong> La calidad del software empieza por la calidad de los requerimientos.<br><br><strong>Pregunta desafío:</strong> ¿qué concepto de la unidad aplicarían primero en un proyecto?<br><br><strong>Respuestas posibles:</strong> 1. La obtención con fuentes y técnicas. 2. La especificación con el documento ERS. 3. La gestión de cambios.<br><br><strong>Advertencia:</strong> el cierre resume; la práctica en los trabajos del curso consolida los conceptos.' }
];

const stage = document.querySelector('#stage');
const indexPanel = document.querySelector('#index-panel');
const notesPanel = document.querySelector('#notes-panel');
const index = document.querySelector('#slide-index');
const notes = document.querySelector('#speaker-notes');
const printAll = new URLSearchParams(location.search).get('print') === 'all';
let current = 0;

function slideMarkup(slide, position) {
  return `<article class="slide slide-${position + 1}" aria-labelledby="slide-title"><div><p class="eyebrow">${slide.eyebrow}</p><h1 id="slide-title">${slide.title}</h1><div class="content">${slide.body}</div></div><div class="visual">${slide.visual}</div><span class="slide-number">${String(position + 1).padStart(2, '0')}</span></article>`;
}

function render() {
  const slide = slides[current];
  stage.innerHTML = slideMarkup(slide, current);
  document.querySelector('#counter').textContent = `${String(current + 1).padStart(2, '0')} / ${String(slides.length).padStart(2, '0')}`;
  const progress = document.querySelector('#progress');
  progress.style.width = `${((current + 1) / slides.length) * 100}%`;
  progress.setAttribute('aria-valuenow', current + 1);
  notes.innerHTML = `<div class="note"><strong>Slide ${current + 1}: ${slide.title}</strong><p>${slide.note}</p></div>`;
  document.querySelectorAll('.index-item').forEach((button, i) => button.classList.toggle('active', i === current));
  history.replaceState(null, '', `#slide-${current + 1}`);
}
function renderAllForPrint() { stage.innerHTML = slides.map((slide, position) => slideMarkup(slide, position)).join(''); }
function goTo(position) { current = Math.max(0, Math.min(slides.length - 1, position)); render(); document.querySelector('#main-content').focus({ preventScroll: true }); }
function toggle(panel, force) { const open = typeof force === 'boolean' ? force : !panel.classList.contains('open'); panel.classList.toggle('open', open); panel.setAttribute('aria-hidden', String(!open)); const control = document.querySelector(`[aria-controls="${panel.id}"]`); if (control) control.setAttribute('aria-expanded', String(open)); if (open) panel.querySelector('button, [href]')?.focus(); }
slides.forEach((slide, i) => { const button = document.createElement('button'); button.className = 'index-item'; button.type = 'button'; button.textContent = `${String(i + 1).padStart(2, '0')} · ${slide.title}`; button.addEventListener('click', () => { goTo(i); toggle(indexPanel, false); }); index.append(button); });
document.querySelector('#next').addEventListener('click', () => goTo(current + 1));
document.querySelector('#previous').addEventListener('click', () => goTo(current - 1));
document.querySelector('#index-toggle').addEventListener('click', () => toggle(indexPanel));
document.querySelector('#notes-toggle').addEventListener('click', () => toggle(notesPanel));
document.querySelectorAll('.close-panel').forEach(button => button.addEventListener('click', () => toggle(document.querySelector(`#${button.dataset.close}`), false)));
document.querySelector('#fullscreen').addEventListener('click', () => document.documentElement.requestFullscreen?.());
document.addEventListener('keydown', event => { if (event.key === 'Escape') { toggle(indexPanel, false); toggle(notesPanel, false); } if (['ArrowRight', 'PageDown', ' '].includes(event.key)) { event.preventDefault(); goTo(current + 1); } if (['ArrowLeft', 'PageUp'].includes(event.key)) { event.preventDefault(); goTo(current - 1); } if (event.key === 'Home') { event.preventDefault(); goTo(0); } if (event.key === 'End') { event.preventDefault(); goTo(slides.length - 1); } if (event.key.toLowerCase() === 'n') toggle(notesPanel); if (event.key.toLowerCase() === 'i') toggle(indexPanel); });
window.addEventListener('hashchange', () => { const match = location.hash.match(/slide-(\d+)/); if (match) goTo(Number(match[1]) - 1); });
const initial = location.hash.match(/slide-(\d+)/); if (initial) current = Number(initial[1]) - 1;
if (printAll) renderAllForPrint(); else render();
